-- V21 - Recarrega a tabela completa de custos da planilha 25/05/26 com status de compra e valores.
-- Não apaga fotos e não altera posições do mapa.

-- =========================================================
-- STEP Obras | Atualização v21 - CUSTOS COMPLETOS + STATUS DE COMPRA
-- Fonte: Melhorias base STEP 25-05-26.xlsx
--
-- O que esta versão corrige:
--   * Recarrega a aba "Custos x Execução" completa: 311 linhas.
--   * Mantém todos os status de compra e seus valores:
--       - Cancelado: 26 linhas | R$ 14,395,357.05
--       - Orçamento não Aprovado: 71 linhas | R$ 7,025,327.01
--       - Comprado: 195 linhas | R$ 1,618,675.14
--       - Em Orçamento: 18 linhas | R$ 242,003.05
--       - Em Processo de Compra: 1 linhas | R$ 0.00
--   * Total bruto da aba Custos x Execução: R$ 23,281,362.25
--   * Total vinculado aos itens do mapa: R$ 23,125,805.25
--   * Total sem vínculo direto: R$ 155,557.00
--   * Não altera fotos.
--   * Não altera posições X/Y existentes no mapa.
-- =========================================================

begin;

create extension if not exists pgcrypto;

-- Garante colunas necessárias da tabela de obras sem quebrar banco existente
alter table public.step_obras_items add column if not exists custo_comprado numeric(16,4) not null default 0;
alter table public.step_obras_items add column if not exists status_compra public.step_status_compra not null default 'Não informado';
alter table public.step_obras_items add column if not exists ordem integer;
alter table public.step_obras_items add column if not exists ativo boolean not null default true;
alter table public.step_obras_items add column if not exists metadata jsonb not null default '{}'::jsonb;

create table if not exists public.step_obras_costs (
  id bigserial primary key,
  row_key text not null unique,
  item_id text references public.step_obras_items(id) on delete set null,
  setor text,
  cotacao text,
  data_cotacao date,
  pedido text,
  data_pedido date,
  fornecedor text,
  produto text,
  quantidade numeric(16,3) default 0,
  valor numeric(16,4) default 0,
  origem text,
  status_compra text default 'Não informado',
  disciplina text,
  observacao text,
  source text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.step_obras_costs alter column valor type numeric(16,4) using valor::numeric(16,4);
alter table public.step_obras_costs alter column quantidade type numeric(16,3) using quantidade::numeric(16,3);

create index if not exists idx_step_obras_costs_item_id on public.step_obras_costs(item_id);
create index if not exists idx_step_obras_costs_status on public.step_obras_costs(status_compra);
create index if not exists idx_step_obras_costs_setor on public.step_obras_costs(setor);
create index if not exists idx_step_obras_costs_pedido on public.step_obras_costs(pedido);

alter table public.step_obras_costs enable row level security;
drop policy if exists "step_obras_costs_select" on public.step_obras_costs;
create policy "step_obras_costs_select"
on public.step_obras_costs for select
to anon, authenticated
using (true);

