insert into public.step_obras_items
(id, area, title, status, progress, owner, priority, cost, custo_comprado, due, x, y, next_action, notes, ordem, ativo, metadata, updated_at)
select
  id,
  area,
  title,
  status::public.step_obra_status,
  progress,
  owner,
  priority::public.step_prioridade,
  cost,
  custo_comprado,
  due,
  x,
  y,
  next_action,
  notes,
  ordem,
  true,
  coalesce(metadata, '{}'::jsonb),
  now()
from src
on conflict (id) do update set
  area = excluded.area,
  title = excluded.title,
  status = excluded.status,
  progress = excluded.progress,
  owner = excluded.owner,
  priority = excluded.priority,
  cost = excluded.cost,
  custo_comprado = excluded.custo_comprado,
  due = excluded.due,
  -- preserva posições já ajustadas no mapa:
  x = coalesce(public.step_obras_items.x, excluded.x),
  y = coalesce(public.step_obras_items.y, excluded.y),
  next_action = excluded.next_action,
  notes = excluded.notes,
  ordem = excluded.ordem,
  ativo = true,
  metadata = coalesce(public.step_obras_items.metadata, '{}'::jsonb) || excluded.metadata,
  updated_at = now();

-- 2) Recarrega tabela detalhada de custos
