-- 3) Sincroniza custo dos itens pelo somatório real da tabela detalhada
update public.step_obras_items i
set
  cost = coalesce(t.total,0),
  custo_comprado = coalesce(t.comprado,0),
  status_compra = case
    when coalesce(t.comprado,0) > 0 then 'Comprado'::public.step_status_compra
    when coalesce(t.em_orcamento,0) > 0 then 'Em Orçamento'::public.step_status_compra
    when coalesce(t.em_processo,0) > 0 then 'Em Processo de Compra'::public.step_status_compra
    when coalesce(t.cancelado,0) > 0 then 'Cancelado'::public.step_status_compra
    when coalesce(t.nao_aprovado,0) > 0 then 'Orçamento não Aprovado'::public.step_status_compra
    else 'Não informado'::public.step_status_compra
  end,
  updated_at = now()
from (
  select
    item_id,
    sum(valor) as total,
    sum(valor) filter (where status_compra = 'Comprado') as comprado,
    sum(valor) filter (where status_compra = 'Em Orçamento') as em_orcamento,
    sum(valor) filter (where status_compra = 'Em Processo de Compra') as em_processo,
    sum(valor) filter (where status_compra = 'Cancelado') as cancelado,
    sum(valor) filter (where status_compra = 'Orçamento não Aprovado') as nao_aprovado
  from public.step_obras_costs
  where item_id is not null
  group by item_id
) t
where i.id = t.item_id;

-- 4) Views para auditoria e conferência
create or replace view public.step_obras_cost_status_summary as
select
  status_compra,
  count(*)::integer as linhas,
  round(sum(valor)::numeric, 2) as valor_total
from public.step_obras_costs
group by status_compra
order by valor_total desc;

create or replace view public.step_obras_cost_item_summary as
select
  item_id,
  count(*)::integer as linhas,
  round(sum(valor)::numeric, 2) as valor_total,
  round(sum(valor) filter (where status_compra = 'Comprado')::numeric, 2) as valor_comprado,
  round(sum(valor) filter (where status_compra = 'Cancelado')::numeric, 2) as valor_cancelado,
  round(sum(valor) filter (where status_compra = 'Orçamento não Aprovado')::numeric, 2) as valor_nao_aprovado,
  round(sum(valor) filter (where status_compra = 'Em Orçamento')::numeric, 2) as valor_em_orcamento,
  round(sum(valor) filter (where status_compra = 'Em Processo de Compra')::numeric, 2) as valor_em_processo
from public.step_obras_costs
where item_id is not null
group by item_id
order by item_id;

create or replace view public.step_obras_cost_sector_summary as
select
  setor,
  count(*)::integer as linhas,
  round(sum(valor)::numeric, 2) as valor_total
from public.step_obras_costs
group by setor
order by valor_total desc;

-- 5) Grava resumo em config para rastreabilidade
